    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteArrayValue == null) {
        if (byteLength > 0) {
            ensureCapacity(size + byteLength);
            for (int i = 0; i < byteLength; i++) {
                bytes[size + i] = 0;
            }
            size += byteLength;
        }
        return this;
    }
    if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array bounds");
    }
    if (byteLength > 0) {
        ensureCapacity(size + byteLength);
        System.arraycopy(byteArrayValue, byteOffset, bytes, size, byteLength);
        size += byteLength;
    }
    return this;
}
