public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    final int length = str.length();
    if (length == 0) {
        return lb;
    }
    final int byteLength = utf8Length(str);
    final int requiredCapacity = byteLength;
    final int availableCapacity = lb.capacity();
    if (availableCapacity < requiredCapacity) {
        lb.reserve(requiredCapacity);
    }
    final int offset = lb.offset();
    final byte[] buffer = lb.buffer();
    int pos = offset;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            buffer[pos++] = (byte) c;
        } else if (c < 0x800) {
            buffer[pos++] = (byte) (0xC0 | (c >> 6));
            buffer[pos++] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0xD800 || c > 0xDFFF) {
            buffer[pos++] = (byte) (0xE0 | (c >> 12));
            buffer[pos++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buffer[pos++] = (byte) (0x80 | (c & 0x3F));
        } else {
            // surrogate pair
            if (i + 1 < length) {
                char low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) {
                    int codePoint = 0x10000 + ((c - 0xD800) << 10) + (low - 0xDC00);
                    buffer[pos++] = (byte) (0xF0 | (codePoint >> 18));
                    buffer[pos++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                    buffer[pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                    buffer[pos++] = (byte) (0x80 | (codePoint & 0x3F));
                    i++;
                } else {
                    // invalid surrogate, write replacement character
                    buffer[pos++] = (byte) 0xE0;
                    buffer[pos++] = (byte) 0xBF;
                    buffer[pos++] = (byte) 0xBD;
                }
            } else {
                // unpaired surrogate, write replacement character
                buffer[pos++] = (byte) 0xE0;
                buffer[pos++] = (byte) 0xBF;
                buffer[pos++] = (byte) 0xBD;
            }
        }
    }
    lb.write(pos - offset);
    return lb;
}
