private void pop(final String descriptor) {
    int count = 0;
    int i = 0;
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);
        if (c == '(') {
            i++;
            while (i < descriptor.length() && descriptor.charAt(i) != ')') {
                c = descriptor.charAt(i);
                if (c == 'L') {
                    int end = descriptor.indexOf(';', i);
                    if (end < 0) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    i = end + 1;
                    count++;
                } else if (c == '[') {
                    i++;
                } else {
                    i++;
                    if (c == 'J' || c == 'D') {
                        count += 2;
                    } else {
                        count++;
                    }
                }
            }
            if (i >= descriptor.length()) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            i++;
            // After the closing parenthesis, the return type follows
            c = descriptor.charAt(i);
            if (c == 'L') {
                int end = descriptor.indexOf(';', i);
                if (end < 0) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                i = end + 1;
                count++;
            } else if (c == '[') {
                i++;
            } else {
                i++;
                if (c == 'J' || c == 'D') {
                    count += 2;
                } else {
                    count++;
                }
            }
        } else {
            // It's a type descriptor, not a method descriptor
            if (c == 'L') {
                int end = descriptor.indexOf(';', i);
                if (end < 0) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                i = end + 1;
                count++;
            } else if (c == '[') {
                i++;
            } else {
                i++;
                if (c == 'J' || c == 'D') {
                    count += 2;
                } else {
                    count++;
                }
            }
        }
    }
    for (int j = 0; j < count; j++) {
        outputFrame.pop();
    }
}

