public void abbreviate(final int nameStart, final StringBuffer buf) {
    int i = nameStart;
    // Skip leading whitespace
    while (i < name.length() && Character.isWhitespace(name.charAt(i))) {
        i++;
    }
    if (i >= name.length()) {
        return;
    }
    // First letter
    char first = Character.toUpperCase(name.charAt(i));
    buf.append(first);
    i++;
    // Skip whitespace
    while (i < name.length() && Character.isWhitespace(name.charAt(i))) {
        i++;
    }
    // Find the next non-whitespace character (start of last name)
    if (i < name.length()) {
        // Check if there's a middle part
        int j = i;
        while (j < name.length() && !Character.isWhitespace(name.charAt(j))) {
            j++;
        }
        if (j < name.length()) {
            // There is a last name, so append the first letter of the last name
            char last = Character.toUpperCase(name.charAt(j));
            buf.append(last);
        }
    }
}
