public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Normalize the path: ensure it ends with a separator if it's a directory
    String normalizedPath = path;
    if (!normalizedPath.endsWith("/")) {
        normalizedPath = normalizedPath + "/";
    }

    // Handle relative path that starts with "/"
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Combine the paths
    String combined = normalizedPath + relativePath;

    // Normalize the combined path by resolving "." and ".." segments
    String[] parts = combined.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else {
            stack.push(part);
        }
    }

    // Reconstruct the path
    StringBuilder result = new StringBuilder();
    // Check if the original path was absolute (starts with /)
    boolean isAbsolute = combined.startsWith("/");
    if (isAbsolute) {
        result.append("/");
    }

    // The stack is in reverse order, so we need to reverse it
    java.util.List<String> reversed = new java.util.ArrayList<>();
    while (!stack.isEmpty()) {
        reversed.add(stack.pop());
    }

    for (int i = 0; i < reversed.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(reversed.get(i));
    }

    // If the result is empty and the path was absolute, return "/"
    if (result.length() == 0) {
        return isAbsolute ? "/" : "";
    }

    return result.toString();
}
